package org.wurmrail;

import com.wurmonline.server.Items;
import com.wurmonline.server.behaviours.Actions;
import com.wurmonline.server.behaviours.Methods;
import com.wurmonline.server.creatures.Creature;
import com.wurmonline.server.items.Item;
import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import org.wurmrail.core.SteamWaterPumps;
import org.wurmrail.core.SteamWaterPumps.Pump;
import org.wurmrail.core.SteamWaterPumpService;
import org.wurmrail.core.SteamWaterPumpService.Result;

/** Authoritative machine-to-source/storage bridge. Every native write stays on the server thread. */
public final class RailwayPumpController {
    private final Path file;private final double rate;private final SteamWaterPumps pumps;private final SteamWaterPumpService service;private final SteamSupplyController supplies;private boolean persistenceFault;
    public RailwayPumpController(Path file,double litresPerSecond)throws IOException {this(file,litresPerSecond,new SteamSupplyController(file.resolveSibling(file.getFileName()+".steam.properties"),SteamSupplyConfig.defaults()));}
    public RailwayPumpController(Path file,double litresPerSecond,SteamSupplyController supplies)throws IOException {this.file=file;this.supplies=java.util.Objects.requireNonNull(supplies);rate=litresPerSecond;pumps=SteamWaterPumps.load(file);service=new SteamWaterPumpService(pumps,new SteamWaterPumpService.World(){@Override public Result pump(Pump state,long allowance){Item machine=Items.getItemOptional(state.itemId).orElse(null);String reason=machineProblem(machine,state);if(reason!=null)return machine!=null&&(machine.isLocked()||machine.isSealedByPlayer())?Result.waiting("Waiting: "+reason):Result.fault(0,"Stopped: "+reason);if(state.sourceX<0)return Result.waiting("Waiting: select a nearby natural water source.");reason=NaturalWaterSources.problem(machine,state.sourceX,state.sourceY,state.sourceLayer);if(reason!=null)return Result.waiting("Waiting: "+reason);if(state.tankId<=0)return Result.waiting("Waiting: select a linked Industrial Water Tank.");Item tank=Items.getItemOptional(state.tankId).orElse(null);reason=MachineWaterSources.storageProblem(machine.getPosX(),machine.getPosY(),state.layer,tank,state.ownerId,MachineWaterSources.LINK_REACH);if(reason!=null)return Result.waiting("Waiting: "+reason);boolean salted=NaturalWaterSources.salted(state.sourceX,state.sourceY,state.sourceLayer);LiquidTankTransfers.Result added=NaturalWaterProduction.add(tank,state.ownerId,allowance,salted,RailwayPumpController.this.supplies.work(machine,state.ownerId,RailwayPumpController.this.supplies.config().pumpEnergyPerLitre,0));if(added.requiresOperatorIntervention)return Result.fault(added.transferredMillilitres,"Stopped for recovery: "+added.status);return added.transferredMillilitres>0?Result.pumped(added.transferredMillilitres,"Pumping water into the linked Industrial Water Tank."):Result.waiting("Waiting: "+added.status);}},litresPerSecond);}
    public SteamWaterPumps state(){return pumps;}
    public SteamSupplyController supplies(){return supplies;}
    private static String machineProblem(Item machine,Pump state){if(!RailwaySteamWaterPump.isPump(machine))return "The Steam Water Pump no longer exists.";if(!MachineStorageLinks.placed(machine))return "Place the pump on ground level, outside inventories, bridges and trades.";if(!machine.isOwner(state.ownerId))return "Pump ownership changed. Stop and save its settings again.";if(machine.isOnSurface()!=(state.layer==0)||machine.getTileX()!=state.tileX||machine.getTileY()!=state.tileY)return "The pump was moved. Stop and save its source and tank settings at the new location.";if(machine.isLocked()||machine.isSealedByPlayer())return "Unlock and unseal the Steam Water Pump.";return null;}
    private static Item nearby(Creature actor,long id){Item machine=Items.getItemOptional(id).orElse(null);if(actor==null||!RailwaySteamWaterPump.isPump(machine)||!MachineStorageLinks.placed(machine)||actor.isOnSurface()!=machine.isOnSurface()||actor.getFloorLevel()!=0||actor.getBridgeId()!=-10L||Math.hypot(actor.getPosX()-machine.getPosX(),actor.getPosY()-machine.getPosY())>8)throw new IllegalArgumentException("Stand within eight metres of the Steam Water Pump on the same ground level.");return machine;}
    private static long owner(Item machine,Pump state){long id=machine.getLastOwnerId();return id>0?id:state==null?0:state.ownerId;}
    private static boolean mayControl(Creature actor,Item machine,long owner){return actor.getPower()>=2||owner>0&&actor.getWurmId()==owner&&machine.isOwner(owner)&&machine.mayAccessHold(actor)&&Methods.isActionAllowed(actor,Actions.OPEN,machine);}
    private static void requireControl(Creature actor,Item machine,long owner){if(!mayControl(actor,machine,owner))throw new IllegalArgumentException("Only the pump's owner or a GM may control it.");}
    private static boolean current(Item machine,Pump state,long owner){return state!=null&&state.ownerId==owner&&state.tileX==machine.getTileX()&&state.tileY==machine.getTileY()&&state.layer==(machine.isOnSurface()?0:-1);}
    public RailwaySteamWaterPump.View snapshot(Creature actor,long id){Item machine=nearby(actor,id);Pump state=pumps.get(id);long owner=owner(machine,state);boolean control=mayControl(actor,machine,owner),current=current(machine,state,owner);List<RailwaySteamWaterPump.TankChoice> tanks=new ArrayList<RailwaySteamWaterPump.TankChoice>();List<RailwaySteamWaterPump.SourceChoice> sources=new ArrayList<RailwaySteamWaterPump.SourceChoice>();if(control){for(Item tank:MachineWaterSources.nearbyTanks(actor,machine,owner))tanks.add(new RailwaySteamWaterPump.TankChoice(tank.getWurmId(),tank.getName()+" ["+tank.getWurmId()+"]"));for(NaturalWaterSources.Source source:NaturalWaterSources.nearby(machine))sources.add(new RailwaySteamWaterPump.SourceChoice(source.x,source.y,source.layer,source.label));}long tankId=current?state.tankId:0;Item tank=Items.getItemOptional(tankId).orElse(null);String tankSummary=tankId<=0?"None":tank==null?"Missing tank ["+tankId+"]":tank.getName()+" ["+tankId+"]; "+LiquidTankPolicy.summary(tank);String sourceSummary=!current||state.sourceX<0?"None":state.sourceX+", "+state.sourceY+(state.sourceLayer==0?" (surface)":" (cave)");String status=state==null?"Choose nearby natural water and an Industrial Water Tank, then start pumping.":!current?"Location or ownership changed. Stop and Save settings before starting.":state.status;return new RailwaySteamWaterPump.View(id,state==null?-1:state.revision,machine.getName(),current&&state.running,tankId,current?state.sourceX:-1,current?state.sourceY:-1,current?state.sourceLayer:0,status,tankSummary,sourceSummary,rate,tanks,sources,control,supplies.snapshot(actor,machine,owner,false));}
    public void apply(Creature actor,long id,RailwaySteamWaterPump.Request request)throws IOException {if(request==null||request.id!=id)throw new IllegalArgumentException("Choose this pump's current controls.");if(request.action==RailwaySteamWaterPump.ActionType.REFRESH){nearby(actor,id);return;}Item machine=nearby(actor,id);Pump previous=pumps.get(id);long owner=owner(machine,previous);requireControl(actor,machine,owner);if(request.action==RailwaySteamWaterPump.ActionType.STOP){stop(actor,id);return;}if((previous==null?-1:previous.revision)!=request.revision)throw new IllegalArgumentException("The pump settings changed. Refresh before saving.");boolean changed=previous!=null&&!current(machine,previous,owner);if(changed&&(previous.running||request.action==RailwaySteamWaterPump.ActionType.START))throw new IllegalArgumentException("Stop the moved or newly owned pump, then Save settings before starting.");if(owner<=0&&actor.getPower()>=2){owner=actor.getWurmId();machine.setLastOwnerId(owner);}if(owner<=0)throw new IllegalArgumentException("This pump has no owner. A GM must claim it.");if(request.tankId>0)MachineWaterSources.validateSelection(actor,machine,Items.getItemOptional(request.tankId).orElse(null),owner);if(request.sourceX>=0)NaturalWaterSources.validateSelection(actor,machine,owner,request.sourceX,request.sourceY,request.sourceLayer);supplies.configure(actor,machine,owner,false,request.supplies);if(previous!=null&&previous.running)service.stop(id);pumps.put(new Pump(id,owner,pumps.nextRevision(),machine.getTileX(),machine.getTileY(),machine.isOnSurface()?0:-1,request.tankId,request.sourceX,request.sourceY,request.sourceLayer,false,"Settings saved. Stopped."));service.reset(id);if(request.action==RailwaySteamWaterPump.ActionType.START)start(actor,id);else save();}
    public void start(Creature actor,long id)throws IOException {Item machine=nearby(actor,id);Pump state=pumps.get(id);requireControl(actor,machine,owner(machine,state));if(state==null)throw new IllegalArgumentException("Select natural water and an Industrial Water Tank, then save settings first.");if(!current(machine,state,owner(machine,state)))throw new IllegalArgumentException("The pump moved or changed owner. Stop and Save settings before starting.");service.start(id);save();}
    public void stop(Creature actor,long id)throws IOException {Item machine=nearby(actor,id);Pump state=pumps.get(id);requireControl(actor,machine,owner(machine,state));if(state==null)return;service.stop(id);save();}
    public void tick(double elapsed)throws IOException {if(persistenceFault)return;service.tick(elapsed);if(service.dirty())save();}
    public void save()throws IOException {try{pumps.save(file);service.clearDirty();persistenceFault=false;}catch(IOException failure){for(Pump state:new ArrayList<Pump>(pumps.pumps.values()))if(state.running)pumps.put(state.withProgress(false,"Stopped: pump controls could not be saved. Check server storage, then start again."));service.close();persistenceFault=true;throw failure;}}
}
